# stdlib-free, import-free, no I/O; deterministic exact integer arithmetic; fail-closed.
# The harness supplies WITNESS below and inspects the final variable RESULT.
WITNESS = {'range': 1000000, 'extremum_a': 5760, 'extremum_n': 15015, 'numerator': 50, 'denominator': 131}

def verify(w):
    N = int(w['range'])
    A = int(w['numerator'])
    B = int(w['denominator'])
    ea = int(w['extremum_a'])
    en = int(w['extremum_n'])
    if N <= 0 or A <= 0 or B <= 0 or ea <= 0 or en <= 0:
        return False
    # sieve Euler phi for 1..N
    phi = list(range(N + 1))
    for i in range(2, N + 1):
        if phi[i] == i:  # i is prime
            for j in range(i, N + 1, i):
                phi[j] -= phi[j] // i
    # least preimage n_a for each a <= N in im(phi)
    least = [0] * (N + 1)
    for n in range(1, N + 1):
        a = phi[n]
        if 1 <= a <= N and (least[a] == 0 or n < least[a]):
            least[a] = n
    # exhaustive fail-closed check: A*n_a <= B*a for all a in im(phi), a <= N
    for a in range(1, N + 1):
        n_a = least[a]
        if n_a > 0:
            if A * n_a > B * a:  # exact cross-multiplied integer comparison
                return False
    # extremum certification: minimum n_a/a attained exactly at (ea, en)
    best_a = -1
    best_n = -1
    for a in range(1, N + 1):
        n_a = least[a]
        if n_a > 0:
            if best_a == -1 or n_a * best_a < best_n * a:
                best_a = a
                best_n = n_a
    if best_a != ea or best_n != en:
        return False
    # bound holds strictly at the extremum, cross-multiplied
    if A * en > B * ea:
        return False
    return True

RESULT = verify(WITNESS)
